/**
 * Generated row markers — used by both contentValidation and progressSequence.
 * Extracted to avoid import cycles.
 */

/**
 * Description prefix stamped on rows compiled from a Session Design block:
 * `block:<designId>:<rowIndex>`, so a re-apply replaces exactly its own rows.
 */
export const GeneratedDescriptionPrefix = "block:";

/** True when this row was generated by a Session Design and is replaced on re-apply. */
export function isGeneratedRow(description: string | null | undefined): boolean {
  return typeof description === "string" && description.startsWith(GeneratedDescriptionPrefix);
}
